function normalizeData(saved={}){const {activeDay,...state}=saved||{},catalog=(Array.isArray(saved.catalog)?saved.catalog:structuredClone(seed.catalog)).map(item=>{const {rest,...entry}=item;return {...entry,group:muscleGroups.includes(entry.group)?entry.group:'Sonstige'}}),plan=(Array.isArray(saved.plan)?saved.plan:structuredClone(seed.plan)).map(({day,...w})=>({...w,exercises:(w.exercises||[]).map(({rest,...exercise})=>exercise)}));return {...structuredClone(seed),...state,catalog,plan,history:Array.isArray(saved.history)?saved.history:[]}}
function load(){try{return normalizeData(JSON.parse(localStorage.getItem(KEY)||'{}'))}catch{return normalizeData()}}
function freshData(){return normalizeData({catalog:structuredClone(seed.catalog),plan:structuredClone(seed.plan),history:[]})}
function sessionDraftStorageKey(){return `${SESSION_DRAFT_KEY}:${activeProfileName||'device'}`}
function loadSessionDraft(){try{const draft=JSON.parse(localStorage.getItem(sessionDraftStorageKey())||'null');if(!draft||!Array.isArray(draft.exercises))return null;draft.values=draft.values&&typeof draft.values==='object'?draft.values:{};return draft}catch{return null}}
function resumeSessionRoute(){return sessionDraft?.sourceWorkoutId?`#session?id=${encodeURIComponent(sessionDraft.sourceWorkoutId)}`:'#session?free=1'}
function beginTemplateSession(id){if(sessionDraft?.sourceWorkoutId!==id&&sessionDraft?.exercises.length&&!confirm('Ein Training ist zwischengespeichert. Soll es durch dieses Vorlagen-Training ersetzt werden?'))return;if(sessionDraft?.sourceWorkoutId!==id){const workout=data.plan.find(item=>item.id===id);if(!workout)return;sessionDraft={...structuredClone(workout),exercises:workout.exercises.map(ex=>({...ex,status:"pending"})),sourceWorkoutId:id,values:{}};persistSessionDraft()}location.hash=resumeSessionRoute();render()}
