function save(){localStorage.setItem(KEY,JSON.stringify(data));if(cloudUser)localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));if(cloudUser||localStorage.getItem(CLOUD_OWNER_KEY)){localStorage.setItem(CLOUD_DIRTY_KEY,'1');if(cloudUser){clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(cloudSaveNow,900)}}}
