function createCloudClient(config){if(!window.supabase?.createClient)throw Error('Die Supabase-Bibliothek konnte nicht geladen werden. Prüfe die Internetverbindung.');if(!/^https?:\/\//i.test(config.url)||!config.key)throw Error('Bitte trage Projekt-URL und Publishable Key ein.');cloudClient=window.supabase.createClient(config.url.replace(/\/$/,''),config.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});return cloudClient}
function updateCloudButton(){const button=$('#cloudBtn'),sync=$('#syncBtn'),check=$('#cloudCheck'),mark=$('#profileMark'),connected=Boolean(cloudUser);if(mark){mark.textContent=connected?(activeProfileName||'Carsten').trim().charAt(0).toUpperCase():'?';mark.title=connected?`Profil ${activeProfileName||'verbunden'}`:'Zum Anmelden';mark.setAttribute('aria-label',connected?`Profil ${activeProfileName||'verbunden'}`:'Anmelden');}if(check)check.hidden=!connected;if(sync){sync.classList.toggle('sync-connected',connected);sync.title=connected?`Jetzt mit der Cloud synchronisieren · ${activeProfileName||cloudUser.email||'angemeldet'}`:'Anmelden und synchronisieren';sync.setAttribute('aria-label',sync.title)}if(button){button.title='Settings öffnen';button.setAttribute('aria-label',button.title)}}
async function startCloud(){const config=storedCloudConfig();if(!config.url||!config.key||!window.supabase?.createClient){updateCloudButton();return}try{createCloudClient(config);const {data:result,error}=await cloudClient.auth.getSession();if(error)throw error;const user=result.session?.user;if(user)await activateCloudUser(user,null);updateCloudButton()}catch(error){console.warn('Cloud-Verbindung konnte nicht gestartet werden:',error.message);updateCloudButton()}}
async function cloudFetch(){const {data:row,error}=await cloudClient.from('fitness_data').select('payload,version,updated_at').eq('user_id',cloudUser.id).maybeSingle();if(error)throw error;return row}
function applyCloudRow(row){const incoming=row.payload;if(!isValidFitnessData(incoming))throw Error('Die Cloud-Sicherung enthält kein gültiges GrevingFit-Datenformat.');data=normalizeData(incoming);localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));cloudVersion=Number(row.version);localStorage.setItem(CLOUD_VERSION_KEY,String(cloudVersion));localStorage.setItem(CLOUD_OWNER_KEY,cloudUser.id);localStorage.removeItem(CLOUD_DIRTY_KEY);render();updateCloudButton()}
async function cloudWrite(payload,expectedVersion=null){const now=new Date().toISOString(),values={payload:structuredClone(payload),version:(expectedVersion||0)+1,updated_at:now};let query;if(expectedVersion===null)query=cloudClient.from('fitness_data').insert({user_id:cloudUser.id,...values});else query=cloudClient.from('fitness_data').update(values).eq('user_id',cloudUser.id).eq('version',expectedVersion);const {data:rows,error}=await query.select('version,updated_at').maybeSingle();if(error)throw error;if(!rows)return null;cloudVersion=Number(rows.version);localStorage.setItem(CLOUD_VERSION_KEY,String(cloudVersion));localStorage.setItem(CLOUD_OWNER_KEY,cloudUser.id);localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));localStorage.removeItem(CLOUD_DIRTY_KEY);updateCloudButton();return rows}
async function cloudInitialSync(){if(!cloudClient||!cloudUser||!activeProfileName)return;cloudReady=false;try{const row=await cloudFetch(),owner=localStorage.getItem(CLOUD_OWNER_KEY),sameAccount=owner===cloudUser.id;if(!row){if(owner&&!sameAccount&&!localStorage.getItem(`${KEY}:${cloudUser.id}`)){showEmptyCloudChoices();return}const inserted=await cloudWrite(data,null);if(!inserted)throw Error('Die erste Cloud-Sicherung konnte nicht erstellt werden.');cloudReady=true;toast('Lokale Daten erstmals in der Cloud gesichert');return}const dirty=localStorage.getItem(CLOUD_DIRTY_KEY)==='1';if(!sameAccount||dirty){showCloudChoices(row,!sameAccount?'Diese Cloud enthält bereits Daten. Wähle die Version für '+activeProfileName+'.':'Auf diesem Gerät gibt es noch nicht synchronisierte Änderungen. Wähle die Version, die gelten soll.');return}if(cloudVersion!==Number(row.version)){showCloudChoices(row,'Neuere Cloud-Daten für '+activeProfileName+' sind verfügbar. Möchtest du sie auf dieses Gerät laden?');return}updateCloudButton();cloudReady=true}catch(error){console.error('Cloud-Synchronisierung fehlgeschlagen:',error);toast(`Cloud-Sync fehlgeschlagen: ${error.message||'Verbindung prüfen'}`)}}
function stopCloudWatch(){if(cloudPollTimer){clearInterval(cloudPollTimer);cloudPollTimer=0}}
async function checkCloudForUpdates(){if(!cloudClient||!cloudUser||!activeProfileName||cloudCheckBusy||document.visibilityState==='hidden')return;cloudCheckBusy=true;try{const row=await cloudFetch();if(!row||Number(row.version)<=Number(cloudVersion||0)||Number(row.version)===cloudDeferredVersion)return;const dialog=$('#modal');if(dialog?.open)return;cloudReady=false;const dirty=localStorage.getItem(CLOUD_DIRTY_KEY)==='1';showCloudChoices(row,dirty?'Neuere Cloud-Daten sind verfügbar. Auf diesem Gerät gibt es außerdem noch nicht synchronisierte Änderungen. Wähle, welche Version gelten soll.':'Neuere Cloud-Daten für '+activeProfileName+' sind verfügbar. Möchtest du sie auf dieses Gerät laden?')}catch(error){console.warn('Cloud-Änderungen konnten nicht geprüft werden:',error.message)}finally{cloudCheckBusy=false}}
function startCloudWatch(){stopCloudWatch();if(!cloudClient||!cloudUser)return;cloudPollTimer=setInterval(checkCloudForUpdates,5000)}
async function cloudSaveNow(){if(!cloudClient||!cloudUser||!cloudReady||cloudSaving||localStorage.getItem(CLOUD_DIRTY_KEY)!=='1')return;cloudSaving=true;try{const saved=await cloudWrite(data,cloudVersion);if(!saved){toast('Cloud-Konflikt: Öffne ☁ und wähle die gewünschte Version.');return}toast('Änderungen in der Cloud gespeichert')}catch(error){console.error('Cloud-Speichern fehlgeschlagen:',error);toast('Cloud-Speichern fehlgeschlagen – lokal bleibt alles erhalten')}finally{cloudSaving=false}}
function showCloudChoices(row,message){const existing=$('#modal');if(existing?.open&&existing.dataset.cloudVersion===String(row.version))return;const d=modal(`<h2>Cloud-Daten abgleichen</h2><p>${esc(message)}</p><p class="tiny muted">Cloud-Stand: ${new Date(row.updated_at).toLocaleString('de-DE')}</p><div class="grid"><button class="button" type="button" data-cloud-load>Cloud-Daten auf dieses Gerät laden</button><button class="button secondary" type="button" data-cloud-overwrite>Lokale Daten in die Cloud übernehmen</button><button class="button ghost" type="button" data-close>Später entscheiden</button></div>`);d.dataset.cloudVersion=String(row.version);$('[data-cloud-load]',d).onclick=()=>{try{cloudDeferredVersion=null;applyCloudRow(row);cloudReady=true;d.close();toast('Cloud-Daten geladen')}catch(error){alert(error.message)}};$('[data-cloud-overwrite]',d).onclick=async()=>{try{const saved=await cloudWrite(data,Number(row.version));if(!saved){d.close();showCloudChoices(await cloudFetch(),'Die Cloud wurde zwischenzeitlich geändert. Bitte wähle erneut.');return}cloudReady=true;d.close();toast('Lokale Daten gespeichert')}catch(error){alert(`Cloud-Speichern fehlgeschlagen: ${error.message}`)}};$('[data-close]',d).onclick=()=>{d.close();cloudDeferredVersion=Number(row.version);cloudReady=false}}
function profileSelectMarkup(selected=''){return `<div class="field"><label for="profileName">Profil</label><select id="profileName" name="profileName"><option value="">Profil auswählen …</option>${familyProfiles.map(name=>`<option value="${name}" ${name===selected?'selected':''}>${name}</option>`).join('')}</select></div>`}
async function claimCloudProfile(name){if(!familyProfiles.includes(name))throw Error('Bitte wähle eines der vier Profile.');if(!profileEmailMatches(name,cloudUser?.email))throw Error(`Für ${name} ist ausschließlich ${profileEmails[name]||'die festgelegte E-Mail-Adresse'} zugelassen.`);const {data:profile,error}=await cloudClient.from('fitness_profiles').insert({user_id:cloudUser.id,display_name:name}).select('display_name').single();if(error)throw Error(error.code==='23505'?'Dieses Profil ist bereits vergeben. Bitte wähle ein anderes.':error.message);activeProfileName=profile.display_name;localStorage.setItem(`grevingfit-profile:${cloudUser.id}`,activeProfileName);localStorage.setItem(ACTIVE_PROFILE_KEY,activeProfileName);render();updateCloudButton()}
async function ensureCloudProfile(requestedName=null){const {data:profile,error}=await cloudClient.from('fitness_profiles').select('display_name').eq('user_id',cloudUser.id).maybeSingle();if(error)throw error;if(profile){if(!profileEmailMatches(profile.display_name,cloudUser.email))throw Error(`Dieses Konto passt nicht zum Profil ${profile.display_name}.`);activeProfileName=profile.display_name;localStorage.setItem(`grevingfit-profile:${cloudUser.id}`,activeProfileName);localStorage.setItem(ACTIVE_PROFILE_KEY,activeProfileName);return true}if(requestedName){await claimCloudProfile(requestedName);return true}showProfileClaimModal();return false}
function prepareLocalForUser(userId){const userKey=`${KEY}:${userId}`,saved=localStorage.getItem(userKey),previousOwner=localStorage.getItem(CLOUD_OWNER_KEY);if(saved)data=normalizeData(JSON.parse(saved));else if(previousOwner&&previousOwner!==userId)data=freshData();else data=load();localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(userKey,JSON.stringify(data))}
async function activateCloudUser(user,requestedName=null){persistSessionDraft();stopCloudWatch();cloudDeferredVersion=null;cloudUser=user;cloudReady=false;prepareLocalForUser(user.id);updateCloudButton();if(await ensureCloudProfile(requestedName)){sessionDraft=loadSessionDraft();render();updateCloudButton();cloudVersion=Number(localStorage.getItem(CLOUD_VERSION_KEY))||null;await cloudInitialSync();startCloudWatch()}}
function showEmptyCloudChoices(){const d=modal(`<h2>Neues GrevingFit-Profil</h2><p>Für ${esc(activeProfileName)} gibt es noch keine Cloud-Sicherung.</p><div class="grid"><button class="button" type="button" data-cloud-empty>Mit Beispiel-Vorlagen starten</button><button class="button secondary" type="button" data-cloud-upload>Aktuelle lokale Daten übernehmen</button></div><p class="tiny muted">Die lokalen Daten könnten von einem anderen Profil stammen. Übernimm sie nur, wenn das beabsichtigt ist.</p>`);$('[data-cloud-empty]',d).onclick=async()=>{data=freshData();localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));localStorage.removeItem(CLOUD_DIRTY_KEY);const row=await cloudWrite(data,null);if(row){cloudReady=true;d.close();render();toast('Neues Profil eingerichtet')}};$('[data-cloud-upload]',d).onclick=async()=>{try{const row=await cloudWrite(data,null);if(row){cloudReady=true;d.close();toast('Lokale Daten ins Profil übernommen')}}catch(error){alert(error.message)}}}
function cloudModal(){if(cloudUser){const d=modal(`<h2>Cloud-Synchronisierung</h2><p>Angemeldet als <strong>${esc(activeProfileName||cloudUser.email||'Konto')}</strong><br><span class="tiny muted">${esc(cloudUser.email||'')}</span></p><div class="grid"><button class="button" type="button" data-cloud-sync>Jetzt synchronisieren</button><button class="button secondary" type="button" data-cloud-signout>Abmelden</button></div><p class="tiny muted" style="margin-top:14px">Änderungen werden automatisch synchronisiert. Jedes Familienprofil hat eine eigene Datenablage.</p>`);$('[data-cloud-sync]',d).onclick=()=>{d.close();cloudInitialSync()};$('[data-cloud-signout]',d).onclick=async()=>{persistSessionDraft();stopCloudWatch();await cloudClient.auth.signOut();cloudUser=null;cloudVersion=null;cloudReady=false;activeProfileName='';localStorage.removeItem(ACTIVE_PROFILE_KEY);sessionDraft=loadSessionDraft();data=freshData();localStorage.setItem(KEY,JSON.stringify(data));updateCloudButton();d.close();render();toast('Von der Cloud abgemeldet')};return}const config=storedCloudConfig(),pending=localStorage.getItem('grevingfit-pending-profile')||'',d=modal(`<h2>GrevingFit-Cloud</h2><p>Melde dich an oder erstelle ein persönliches Familienkonto.</p><form id="cloudLoginForm"><div class="field"><label for="cloudEmail">E-Mail</label><input id="cloudEmail" name="email" type="email" required autocomplete="username"></div><div class="field"><label for="cloudPassword">Passwort</label><input id="cloudPassword" name="password" type="password" required autocomplete="current-password"></div>${profileSelectMarkup(pending)}<div class="grid"><button class="button" type="submit">Anmelden</button><button class="button secondary" type="button" data-cloud-signup>Konto erstellen</button></div><p class="tiny muted" id="cloudMessage" style="margin-top:12px"></p></form>`);const form=$('#cloudLoginForm',d),message=$('#cloudMessage',d);form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),profileName=f.get('profileName'),email=f.get('email').trim().toLowerCase();if(!profileEmailMatches(profileName,email)){message.textContent=`Für ${profileName||'das ausgewählte Profil'} ist nur ${profileEmails[profileName]||'die zugehörige E-Mail-Adresse'} zugelassen.`;return}try{createCloudClient(config);const {data:result,error}=await cloudClient.auth.signInWithPassword({email,password:f.get('password')});if(error)throw error;await activateCloudUser(result.user|| (await cloudClient.auth.getUser()).data.user,profileName);if(activeProfileName&&$('#cloudLoginForm',d))d.close()}catch(error){message.textContent=error.message||'Anmeldung fehlgeschlagen.'}};$('[data-cloud-signup]',d).onclick=async()=>{const f=new FormData(form),profileName=f.get('profileName'),email=f.get('email').trim().toLowerCase();if(!profileName){message.textContent='Bitte wähle eines der vier Profile.';return}if(!profileEmailMatches(profileName,email)){message.textContent=`Für ${profileName} ist ausschließlich ${profileEmails[profileName]} zugelassen.`;return}if(!form.reportValidity())return;try{localStorage.setItem('grevingfit-pending-profile',profileName);createCloudClient(config);const {data:result,error}=await cloudClient.auth.signUp({email,password:f.get('password')});if(error)throw error;if(result.session){await activateCloudUser(result.user||result.session.user,profileName);if($('#cloudLoginForm',d))d.close()}else message.textContent='Konto erstellt. Bestätige die E-Mail und melde dich danach mit diesem Profil an.'}catch(error){message.textContent=error.message||'Konto konnte nicht erstellt werden.'}}}
function formatDate(iso,opts={day:'numeric',month:'short',year:'numeric'}){return new Date(iso+'T12:00:00').toLocaleDateString('de-DE',opts)}
function getRoute(){return (location.hash.replace('#','').split('?')[0])||'home'}
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function workouts(){return [...data.history].sort((a,b)=>b.date.localeCompare(a.date))}
function sessionsThisWeek(){const d=new Date(),start=new Date(d);start.setDate(d.getDate()-((d.getDay()+6)%7));start.setHours(0,0,0,0);return data.history.filter(h=>new Date(h.date+'T12:00:00')>=start).length}
function performedExercises(session){return (session.exercises||[]).filter(ex=>ex.status!=='skipped')}
function exerciseSummary(session){const done=performedExercises(session),skipped=(session.exercises||[]).length-done.length;return `${done.length} Übungen · ${done.reduce((n,e)=>n+(e.sets||[]).length,0)} Arbeitssätze${skipped?` · ${skipped} ausgelassen`:''}`}
function volume(session){return performedExercises(session).reduce((sum,e)=>sum+(e.sets||[]).reduce((s,set)=>s+statsNumber(set.weight)*statsNumber(set.reps),0),0)}
function formatWeight(value){if(value===''||value==null)return '';const number=Number(String(value).replace(',','.'));return Number.isFinite(number)?number.toLocaleString('de-DE',{useGrouping:false,maximumFractionDigits:2}):String(value)}
function cleanWeightInput(input){if(input.value.includes('.')){input.value=input.dataset.lastValid??'';return}let value=input.value.replace(/[^0-9,]/g,'');const comma=value.indexOf(',');if(comma!==-1)value=value.slice(0,comma+1)+value.slice(comma+1).replace(/,/g,'');input.value=value;input.dataset.lastValid=value}
function render(){const route=getRoute(),settingsButton=$('#cloudBtn');if(settingsButton){const active=route==='settings';settingsButton.classList.toggle('is-active',active);settingsButton.setAttribute('aria-pressed',String(active))}$$('#appMenu a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));const app=$('#app');if(route==='settings')app.innerHTML=renderSettings();else if(route==='plan')app.innerHTML=renderPlan();else if(route==='catalog')app.innerHTML=renderCatalog();else if(route==='music')app.innerHTML=renderMusic();else if(route==='history')app.innerHTML=renderHistory();else if(route==='stats')app.innerHTML=renderStats();else if(route==='session')app.innerHTML=renderSession();else app.innerHTML=renderHome();$$('.heading-row .subtitle',app).forEach(el=>el.remove());bind()}
function themeMode(){return localStorage.getItem(THEME_KEY)||'light'}
function setTheme(mode){const theme=mode==='dark'?'dark':'light';localStorage.setItem(THEME_KEY,theme);document.documentElement.dataset.theme=theme;render()}
function renderSettings(){const dark=themeMode()==='dark',spotifyClient=localStorage.getItem(SPOTIFY_CLIENT_KEY)||'';return `<div class="eyebrow">APP EINRICHTEN</div><div class="heading-row"><div><h1>Settings</h1><p class="subtitle">Konto, Darstellung, Musik und Datensicherung.</p></div></div><section class="card"><div class="card-head"><h2>Darstellung</h2></div><p class="tiny muted">Wähle ein helles oder dunkles Farbschema.</p><button class="button secondary" type="button" data-theme-toggle>${dark?'☀️ Helles Design aktivieren':'🌙 Dunkles Design aktivieren'}</button></section><section class="card"><div class="card-head"><h2>Login & Cloud-Synchronisierung</h2><span class="pill">${cloudUser?'Verbunden':'Nicht verbunden'}</span></div>${cloudUser?`<div class="settings-account"><div><span class="tiny muted">Profil</span><strong>${esc(activeProfileName||'GrevingFit')}</strong></div><div><span class="tiny muted">E-Mail</span><strong>${esc(cloudUser.email||'')}</strong></div></div><p class="tiny muted">${cloudReady?'Cloud-Synchronisierung aktiv. Änderungen werden automatisch gesichert.':'Cloud-Konto verbunden; Synchronisierung wird vorbereitet.'}</p><div class="split settings-actions"><button class="button" type="button" data-action="settings-cloud-sync">Jetzt synchronisieren</button><button class="button secondary" type="button" data-action="settings-cloud-signout">Abmelden</button></div><details class="settings-password"><summary>Passwort ändern</summary><form id="accountPasswordForm"><div class="field"><label for="newPassword">Neues Passwort</label><input id="newPassword" name="password" type="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label for="confirmPassword">Neues Passwort wiederholen</label><input id="confirmPassword" name="confirmPassword" type="password" minlength="8" autocomplete="new-password" required></div><button class="button secondary" type="submit">Passwort aktualisieren</button><p id="passwordStatus" class="tiny muted" role="status"></p></form></details>`:`<p class="muted tiny">Melde dich mit deinem Profil an oder erstelle das Konto für dein Profil.</p><button class="button" type="button" data-action="settings-cloud-manage">Anmelden oder Konto erstellen</button>`}</section><section class="card"><div class="card-head"><h2>Spotify</h2><span class="spotify-brand">Spotify</span></div><p class="tiny muted">Hinterlege deine Spotify Developer Client ID. Die Redirect URI muss in deiner Spotify-App eingetragen sein.</p><form id="spotifySettingsForm"><div class="field"><label for="spotifyClientId">Spotify Client ID</label><input id="spotifyClientId" name="clientId" value="${esc(spotifyClient)}" autocomplete="off" placeholder="Client ID aus developer.spotify.com"></div><div class="split settings-actions"><button class="button" type="submit">Client ID speichern</button><a class="button secondary" href="#music">Musik öffnen</a></div></form><p class="tiny muted">Redirect URI: <code>${esc(spotifyRedirectUri())}</code></p></section><section class="card"><div class="card-head"><h2>Daten auf diesem Gerät</h2></div><p class="tiny muted">Sichere alle Planungen, Katalogeinträge und den Trainingsverlauf oder stelle ein Backup wieder her.</p><div class="split settings-actions"><button class="button" type="button" data-export-backup>⇅ Sicherung exportieren</button><label class="button secondary" for="importFile">Sicherung importieren</label><input id="importFile" type="file" accept="application/json,.json" hidden></div><p class="tiny muted" style="margin-top:12px">Die Sicherungsdatei enthält Trainingsdaten und Spotify-Link, aber keine Login-Passwörter.</p></section>`}
function renderHome(){const sessions=workouts(),last=sessions[0],name=activeProfileName?` · ${esc(activeProfileName)}`:'',draft=sessionDraft;return `${draft?`<section class="card saved-session-draft"><div class="draft-summary"><div><div class="eyebrow">TRAINING ZWISCHENGESPEICHERT</div><strong>${esc(draft.name||'Spontanes Training')}</strong><span>${draft.exercises.length} Übungen · lokal auf diesem Gerät</span></div><div class="split"><button class="button small" type="button" data-action="resume-session">Fortsetzen →</button><button class="icon-action" type="button" data-action="discard-session-draft" aria-label="Entwurf löschen">×</button></div></div></section>`:''}<div class="eyebrow">${new Date().toLocaleDateString('de-DE',{weekday:'long',day:'numeric',month:'long'})}${name}</div><div class="heading-row"><div><h1 class="hero-title">Zeit für dich.</h1><p class="subtitle">Ein guter Satz nach dem anderen.</p></div></div><div class="grid stats-grid"><div class="metric"><div class="metric-label">Einheiten diese Woche</div><div class="metric-value">${sessionsThisWeek()}</div><div class="metric-note">Konstanz zählt</div></div><div class="metric"><div class="metric-label">Trainings gesamt</div><div class="metric-value">${data.history.length}</div><div class="metric-note">Jede Einheit zählt</div></div><div class="metric"><div class="metric-label">Zuletzt trainiert</div><div class="metric-value" style="font-size:20px">${last?formatDate(last.date,{day:'numeric',month:'short'}):'–'}</div><div class="metric-note">${last?esc(last.name):'Dein Startpunkt'}</div></div></div><section class="workout-banner"><div><div class="eyebrow">DEIN TRAINING</div><h2>Heute trainieren?</h2><p>Stelle spontan eine Einheit zusammen oder starte mit einer Vorlage.</p></div><button class="button" data-action="free-session">Freies Training starten →</button></section><section class="card"><div class="card-head"><h2>Deine Vorlagen</h2><a href="#plan" class="tiny muted">Alle Vorlagen →</a></div>${data.plan.length?data.plan.slice(0,3).map(w=>`<div class="exercise-row"><div class="exercise-number">▤</div><div class="exercise-info"><strong>${esc(w.name)}</strong><span>${w.exercises.length} Übungen</span></div><button class="button small" data-start="${w.id}">Starten</button></div>`).join(''):`<div class="empty">Noch keine Vorlagen. Du kannst eine freie Einheit erstellen und als Vorlage speichern.</div>`}</section><section class="card"><div class="card-head"><h2>Letzte Einheit</h2><a href="#history" class="tiny muted">Verlauf ansehen →</a></div>${last?historyRow(last):`<div class="empty"><div class="empty-icon">↗</div><strong>Dein Fortschritt beginnt hier</strong><p>Protokolliere deine erste Einheit, um deinen Verlauf zu sehen.</p></div>`}</section>`}
function exerciseTargetText(value){const text=String(value??'');return /(?:Sek\.?|sec|Wdh\.?|\bs)\s*$/i.test(text)?text:`${text} Wdh`}
function exerciseRow(e,i){return `<div class="exercise-row"><div class="exercise-number">${String(i+1).padStart(2,'0')}</div><div class="exercise-info"><strong>${esc(e.name)}</strong><span>${e.sets} Sätze · ${esc(exerciseTargetText(e.reps))}</span></div><div class="exercise-meta">${bestFor(e.name)||'–'}</div></div>`}
function bestFor(name){for(const s of workouts())for(const e of s.exercises||[])if(e.name===name&&e.status!=='skipped'){const best=Math.max(0,...(e.sets||[]).map(x=>statsNumber(x.weight)));if(best)return `${best} kg`; }return ''}
function renderPlan(){return `<div class="eyebrow">TRAININGSABLAUF</div><div class="heading-row"><div><h1>Einheiten & Vorlagen</h1><p class="subtitle">Keine Wochenbindung – trainiere, wann du möchtest.</p></div><button class="button" data-action="new-workout">＋ Vorlage erstellen</button></div><section class="workout-banner"><div><div class="eyebrow">FLEXIBEL TRAINIEREN</div><h2>Spontan zusammenstellen</h2><p>Übungen für eine einzelne Einheit auswählen und direkt protokollieren.</p></div><button class="button" data-action="free-session">Freies Training →</button></section><section class="card"><div class="card-head"><h2>${data.plan.length} Vorlagen</h2><a href="#catalog" class="tiny muted">Übungskatalog →</a></div>${data.plan.length?data.plan.map(w=>`<article class="template-card"><div class="card-head"><div><h2>${esc(w.name)}</h2><span class="tiny muted">${w.exercises.length} Übungen</span></div><div class="exercise-actions"><button class="icon-action" title="Vorlage bearbeiten" data-edit-workout="${esc(w.id)}">✎</button><button class="icon-action" title="Vorlage löschen" data-delete-workout="${esc(w.id)}">×</button></div></div>${w.exercises.map((e,i)=>planExerciseRow(e,i,w.id)).join('')}<div class="split template-actions"><button class="button secondary small" data-add-exercise="${esc(w.id)}">＋ Übung</button><button class="button small" data-start="${esc(w.id)}">Einheit starten →</button></div></article>`).join(''):`<div class="empty"><strong>Noch keine Vorlagen</strong><p>Erstelle eine Vorlage oder speichere ein freies Training als Vorlage.</p></div>`}</section>`}
function planExerciseRow(e,i,id){return `<div class="exercise-row"><div class="exercise-number">${String(i+1).padStart(2,'0')}</div><div class="exercise-info"><strong>${esc(e.name)}</strong><span>${e.sets} Sätze · ${esc(exerciseTargetText(e.reps))}</span></div><div class="exercise-actions"><button class="icon-action" title="Übung bearbeiten" data-edit-exercise="${id}:${i}">✎</button><button class="icon-action" title="Übung entfernen" data-delete-exercise="${id}:${i}">×</button></div></div>`}
function catalogItem(name){return (data.catalog||[]).find(item=>item.name.toLocaleLowerCase()===name.toLocaleLowerCase())}
function lastExerciseUse(name){for(const session of workouts()){const exercise=(session.exercises||[]).find(item=>item.name===name&&item.status!=='skipped');if(exercise)return {session,exercise}}return null}
function lastValueText(name){const last=lastExerciseUse(name);if(!last)return 'Noch nicht verwendet';const sets=last.exercise.sets||[],weight=Math.max(0,...sets.map(set=>statsNumber(set.weight))),values=sets.map(set=>set.seconds!==''&&set.seconds!=null?`${set.seconds} Sek.`:set.reps!==''&&set.reps!=null?`${set.reps} Wdh.`:'').filter(Boolean);return `${sets.length||'–'} Sätze${weight?` · bis ${formatWeight(weight)} kg`:''}${values.length?` · zuletzt ${values.join(' / ')}`:''} · ${formatDate(last.session.date,{day:'numeric',month:'short'})}`}
function renderCatalog(){const groups=muscleGroups.filter(group=>(data.catalog||[]).some(item=>(item.group||'Sonstige')===group)).sort((a,b)=>a==='Sonstige'?1:b==='Sonstige'?-1:a.localeCompare(b,'de',{sensitivity:'base'}));return `<div class="eyebrow">DEIN ÜBUNGSVORRAT</div><div class="heading-row"><div><h1>Übungskatalog</h1><p class="subtitle">Übungen und die zuletzt verwendeten Satzwerte.</p></div></div><section class="card"><div class="card-head"><h2>${(data.catalog||[]).length} Übungen</h2><a href="#plan" class="tiny muted">Zu Einheiten →</a></div><p class="tiny muted">Satzwerte werden aus der letzten Verwendung übernommen.</p></section>${groups.map(group=>`<section class="card"><div class="card-head"><h2>${esc(group)}</h2></div>${data.catalog.filter(item=>(item.group||'Sonstige')===group).slice().sort((a,b)=>a.name.localeCompare(b.name,'de',{sensitivity:'base'})).map(item=>`<div class="exercise-row"><div class="exercise-number">↗</div><div class="exercise-info"><strong>${esc(item.name)}</strong><span>${item.sets} Sätze · ${esc(exerciseTargetText(item.reps))}</span><span class="tiny" style="color:var(--lime)">Zuletzt: ${esc(lastValueText(item.name))}</span></div><div class="exercise-actions"><button class="icon-action" title="Übung bearbeiten" data-catalog-edit="${esc(item.name)}">✎</button><button class="icon-action" title="Übung löschen" data-catalog-delete="${esc(item.name)}">×</button></div></div>`).join('')}</section>`).join('')}<section class="card"><div class="card-head"><h2>Eigene Übung hinzufügen</h2></div><p class="muted tiny">Wähle eine Muskelgruppe aus der festen Liste.</p><button class="button secondary small" data-action="catalog-add">＋ Neue Katalogübung</button></section>`}
function spotifyTarget(input){const value=(input||'').trim(),url=value.match(/open\.spotify\.com\/(playlist|track|album|artist|show|episode)\/([A-Za-z0-9]+)/),uri=value.match(/^spotify:(playlist|track|album|artist|show|episode):([A-Za-z0-9]+)$/);if(url)return {type:url[1],id:url[2],link:`https://open.spotify.com/${url[1]}/${url[2]}`,uri:`spotify:${url[1]}:${url[2]}`};if(uri)return {type:uri[1],id:uri[2],link:`https://open.spotify.com/${uri[1]}/${uri[2]}`,uri:`spotify:${uri[1]}:${uri[2]}`};return null}

function setSpotifyStatus(text){spotifyPlaybackStatus=text;const el=$('#spotifyStatus');if(el)el.textContent=text}
function base64url(buffer){return btoa(String.fromCharCode(...new Uint8Array(buffer))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function spotifyRedirectUri(){return location.origin+location.pathname}
async function spotifyConnect(){if(spotifyProfileToken()){await initializeSpotifyPlayer();return}const clientId=$('#spotifyClientId')?.value.trim()||localStorage.getItem(SPOTIFY_CLIENT_KEY)||'';if(!clientId){alert('Trage zuerst deine Spotify Client-ID ein.');return}localStorage.setItem(SPOTIFY_CLIENT_KEY,clientId);const verifier=base64url(crypto.getRandomValues(new Uint8Array(64))),challenge=base64url(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))),state=base64url(crypto.getRandomValues(new Uint8Array(24)));sessionStorage.setItem(SPOTIFY_VERIFIER_KEY,verifier);sessionStorage.setItem(SPOTIFY_STATE_KEY,state);const url=new URL('https://accounts.spotify.com/authorize');url.search=new URLSearchParams({client_id:clientId,response_type:'code',redirect_uri:spotifyRedirectUri(),scope:'streaming user-read-email user-read-private user-read-playback-state user-modify-playback-state',code_challenge_method:'S256',code_challenge:challenge,state}).toString();location.assign(url)}
async function exchangeSpotifyCode(code){const verifier=sessionStorage.getItem(SPOTIFY_VERIFIER_KEY),state=sessionStorage.getItem(SPOTIFY_STATE_KEY),params=new URLSearchParams(location.search);if(!verifier||!state||params.get('state')!==state)throw Error('Spotify-Anmeldung fehlgeschlagen: ungültige Sitzung.');const body=new URLSearchParams({client_id:localStorage.getItem(SPOTIFY_CLIENT_KEY)||'',grant_type:'authorization_code',code,redirect_uri:spotifyRedirectUri(),code_verifier:verifier});const response=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const result=await response.json();if(!response.ok)throw Error(result.error_description||'Spotify-Token konnte nicht abgerufen werden.');spotifyAccessToken=result.access_token;spotifyTokenExpires=Date.now()+result.expires_in*1000;if(result.refresh_token)localStorage.setItem(spotifyRefreshKey(),result.refresh_token);sessionStorage.removeItem(SPOTIFY_VERIFIER_KEY);sessionStorage.removeItem(SPOTIFY_STATE_KEY);history.replaceState({},'',location.pathname+location.hash);setSpotifyStatus('Spotify-Konto verbunden');ensureSpotifySdk()}
async function finishSpotifyCallback(){const params=new URLSearchParams(location.search);if(params.get('error')){history.replaceState({},'',location.pathname+location.hash);toast('Spotify-Anmeldung wurde abgebrochen');return}if(params.get('code')){try{await exchangeSpotifyCode(params.get('code'));await initializeSpotifyPlayer()}catch(error){toast(error.message||'Spotify-Anmeldung fehlgeschlagen')}}}
async function spotifyToken(){if(spotifyAccessToken&&spotifyTokenExpires>Date.now()+60000)return spotifyAccessToken;const refresh=spotifyProfileToken(),clientId=localStorage.getItem(SPOTIFY_CLIENT_KEY);if(!refresh||!clientId)throw Error('Verbinde zuerst dein Spotify Premium-Konto.');const response=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:clientId,grant_type:'refresh_token',refresh_token:refresh})}),result=await response.json();if(!response.ok)throw Error(result.error_description||'Spotify-Anmeldung abgelaufen. Bitte erneut verbinden.');spotifyAccessToken=result.access_token;spotifyTokenExpires=Date.now()+(result.expires_in||3600)*1000;if(result.refresh_token)localStorage.setItem(spotifyRefreshKey(),result.refresh_token);return spotifyAccessToken}
function ensureSpotifySdk(){if(window.Spotify?.Player){initializeSpotifyPlayer();return}if(spotifySdkLoaded)return;spotifySdkLoaded=true;window.onSpotifyWebPlaybackSDKReady=()=>initializeSpotifyPlayer();const script=document.createElement('script');script.src='https://sdk.scdn.co/spotify-player.js';script.async=true;script.onerror=()=>setSpotifyStatus('Spotify-Player konnte nicht geladen werden');document.head.append(script)}
async function initializeSpotifyPlayer(){if(spotifyPlayer)return;try{await spotifyToken();if(!window.Spotify?.Player){ensureSpotifySdk();return}spotifyPlayer=new Spotify.Player({name:'GrevingFit',volume:.7,getOAuthToken:callback=>spotifyToken().then(callback).catch(error=>setSpotifyStatus(error.message))});spotifyPlayer.addListener('ready',({device_id})=>{spotifyDeviceId=device_id;setSpotifyStatus('Player bereit – Wiedergabe über GrevingFit')});spotifyPlayer.addListener('not_ready',()=>{spotifyDeviceId='';setSpotifyStatus('Player nicht erreichbar')});spotifyPlayer.addListener('initialization_error',({message})=>setSpotifyStatus(`Player-Fehler: ${message}`));spotifyPlayer.addListener('authentication_error',({message})=>setSpotifyStatus(`Spotify-Anmeldung fehlgeschlagen: ${message}`));spotifyPlayer.addListener('account_error',({message})=>setSpotifyStatus(`Spotify Premium benötigt: ${message}`));spotifyPlayer.addListener('playback_error',({message})=>setSpotifyStatus(`Wiedergabefehler: ${message}`));spotifyPlayer.addListener('player_state_changed',state=>{updateSpotifyNowPlaying(state);if(spotifyProgressTimer)clearInterval(spotifyProgressTimer);if(state?.paused)spotifyProgressTimer=0;else if(state)spotifyProgressTimer=setInterval(async()=>{const current=await spotifyPlayer?.getCurrentState();if(current)updateSpotifyNowPlaying(current)},1000)});await spotifyPlayer.connect();setSpotifyStatus('Verbinde Spotify-Player …')}catch(error){setSpotifyStatus(error.message||'Spotify konnte nicht verbunden werden')}}
function spotifyTime(ms){const seconds=Math.max(0,Math.floor((+ms||0)/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
function updateSpotifyNowPlaying(state){if(!state)return;const track=state.track_window?.current_track;if(!track)return;const title=$('#spotifyNowTitle'),artist=$('#spotifyNowArtist'),cover=$('#spotifyNowCover'),link=$('#spotifyNowLink'),seek=$('#spotifySeek'),elapsed=$('#spotifyElapsed'),duration=$('#spotifyDuration'),play=$('#spotifyToggle');if(title)title.textContent=track.name||'Spotify';if(artist)artist.textContent=(track.artists||[]).map(a=>a.name).join(' · ');const image=track.album?.images?.[0]?.url||'';if(cover){cover.src=image;cover.hidden=!image;cover.alt=`Cover: ${track.name||'Spotify-Titel'}`}const target=spotifyTarget(track.uri||'');if(link&&target)link.href=target.link;if(seek){seek.max=state.duration||0;seek.value=state.position||0;seek.setAttribute('aria-label',`Wiedergabeposition ${spotifyTime(state.position)} von ${spotifyTime(state.duration)}`)}if(elapsed)elapsed.textContent=spotifyTime(state.position);if(duration)duration.textContent=spotifyTime(state.duration);if(play)play.textContent=state.paused?'▶':'Ⅱ'}
async function searchSpotifyCatalog(query){const status=$('#spotifySearchStatus'),results=$('#spotifyResults');if(!query.trim())return;if(status)status.textContent='Suche bei Spotify …';if(results)results.innerHTML='';try{const token=await spotifyToken(),url=new URL('https://api.spotify.com/v1/search');url.search=new URLSearchParams({q:query.trim(),type:'track,playlist',limit:'8'}).toString();const response=await fetch(url,{headers:{Authorization:`Bearer ${token}`}}),result=await response.json();if(!response.ok)throw Error(result.error?.message||`Spotify-Suche fehlgeschlagen (${response.status})`);const tracks=(result.tracks?.items||[]).map(item=>spotifyResultMarkup(item,'track')),playlists=(result.playlists?.items||[]).filter(Boolean).map(item=>spotifyResultMarkup(item,'playlist'));if(results)results.innerHTML=[...tracks,...playlists].join('')||'<p class="empty">Keine passenden Titel oder Playlists gefunden.</p>';if(status)status.textContent=`${tracks.length+playlists.length} Spotify-Ergebnisse · Inhalte von Spotify`;bindSpotifySearchResults()}catch(error){if(status)status.textContent=error.message||'Spotify-Suche fehlgeschlagen.'}}
function spotifyResultMarkup(item,type){const uri=item.uri||'',target=spotifyTarget(uri);if(!target)return '';const cover=type==='track'?item.album?.images?.[0]?.url:item.images?.[0]?.url,subtitle=type==='track'?(item.artists||[]).map(a=>a.name).join(' · '):(item.owner?.display_name||'Spotify-Playlist');return `<article class="spotify-result"><img src="${esc(cover||'')}" alt="Cover: ${esc(item.name)}" loading="lazy"><div class="spotify-result-info"><a href="${esc(target.link)}" target="_blank" rel="noopener"><strong>${esc(item.name)}</strong></a><span>${esc(subtitle)}</span><small>Auf Spotify öffnen ↗</small></div><div class="spotify-result-actions"><button type="button" class="button small" data-spotify-result-play="${esc(uri)}" aria-label="${type==='track'?'Titel':'Playlist'} abspielen">▶</button><button type="button" class="button secondary small" data-spotify-result-save="${esc(uri)}" aria-label="${type==='track'?'Titel':'Playlist'} speichern">＋</button></div></article>`}
function bindSpotifySearchResults(){$$('[data-spotify-result-play]').forEach(button=>button.onclick=async()=>{const target=spotifyTarget(button.dataset.spotifyResultPlay);if(target){data.musicUrl=target.link;save();const input=$('#spotifyUrl');if(input)input.value=target.link;await playSpotifyTarget(target.uri)}});$$('[data-spotify-result-save]').forEach(button=>button.onclick=()=>{const target=spotifyTarget(button.dataset.spotifyResultSave);if(!target)return;data.musicUrl=target.link;save();const input=$('#spotifyUrl');if(input)input.value=target.link;toast('Spotify-Auswahl gespeichert')})}
async function playSpotifyTarget(raw=data.musicUrl){const target=spotifyTarget(raw);if(!target){setSpotifyStatus('Suche einen Titel oder speichere zuerst einen Spotify-Link.');return}try{await initializeSpotifyPlayer();if(!spotifyPlayer||!spotifyDeviceId){setSpotifyStatus('Player wird verbunden – tippe gleich noch einmal auf Wiedergabe.');return}await spotifyPlayer.activateElement();const token=await spotifyToken(),body=target.type==='track'?{uris:[target.uri]}:{context_uri:target.uri},response=await fetch(`https://api.spotify.com/v1/me/player/play?device_id=${encodeURIComponent(spotifyDeviceId)}`,{method:'PUT',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok){const error=await response.json().catch(()=>({}));throw Error(error.error?.message||`Spotify Player Fehler (${response.status})`)}setSpotifyStatus('Wiedergabe gestartet')}catch(error){setSpotifyStatus(error.message||'Spotify-Wiedergabe fehlgeschlagen')}}
function renderMusic(){const target=spotifyTarget(data.musicUrl),clientId=localStorage.getItem(SPOTIFY_CLIENT_KEY)||'',connected=Boolean(spotifyProfileToken());return `<div class="eyebrow">DEIN TRAININGSSOUND</div><div class="heading-row"><div><h1>Musik</h1><p class="subtitle">Finde Trainingsmusik und spiele sie direkt in GrevingFit ab.</p></div></div><section class="card spotify-connect-card"><div class="card-head"><h2>Spotify verbinden</h2><span class="spotify-brand">Spotify</span></div><p class="muted tiny">GrevingFit nutzt Spotify für Suche und Wiedergabe. Für vollständige Titel ist Spotify Premium erforderlich.</p><p class="tiny muted">Client ID und Redirect URI verwaltest du in <a href="#settings">Settings → Spotify</a>.</p><button class="button" type="button" data-spotify-connect>${connected?'Player verbinden':'Mit Spotify verbinden'}</button><p class="tiny muted" id="spotifyStatus" role="status">${esc(spotifyPlaybackStatus)}</p><p class="tiny muted">Redirect URI für deine Spotify Developer App: <code>${esc(spotifyRedirectUri())}</code></p></section><section class="card spotify-now-card"><div class="card-head"><h2>Aktuelle Wiedergabe</h2><span class="tiny muted">Spotify Connect</span></div><div class="spotify-now"><img id="spotifyNowCover" alt="Cover des aktuellen Titels" hidden><div class="spotify-now-info"><a id="spotifyNowLink" href="https://open.spotify.com" target="_blank" rel="noopener"><strong id="spotifyNowTitle">${target?'Bereit für die Wiedergabe':'Noch kein Titel ausgewählt'}</strong></a><span id="spotifyNowArtist">${target?esc(`${target.type} · ${target.id}`):'Suche nach einem Track oder einer Playlist.'}</span></div></div><div class="spotify-timeline"><span id="spotifyElapsed">0:00</span><input id="spotifySeek" type="range" min="0" max="100" value="0" aria-label="Wiedergabeposition" ${connected?'':'disabled'}><span id="spotifyDuration">0:00</span></div><div class="spotify-controls"><button class="button secondary small" type="button" data-spotify-previous aria-label="Vorheriger Titel">⏮</button><button class="button small spotify-play" type="button" data-spotify-toggle id="spotifyToggle" aria-label="Wiedergabe pausieren oder fortsetzen">▶</button><button class="button secondary small" type="button" data-spotify-next aria-label="Nächster Titel">⏭</button></div></section><section class="card"><div class="card-head"><h2>Musik für dein Training finden</h2><span class="tiny muted">Track oder Playlist</span></div><form id="spotifySearchForm" class="spotify-search-form"><div class="field"><label for="spotifySearch">Spotify-Katalog durchsuchen</label><input id="spotifySearch" name="query" type="search" required placeholder="Titel, Künstler oder Playlist suchen"></div><button class="button" type="submit">Suchen</button></form><p class="tiny muted" id="spotifySearchStatus" role="status">${connected?'Suche mit deinem verbundenen Spotify-Konto.':'Verbinde zuerst Spotify, um Musik zu suchen.'}</p><div id="spotifyResults" class="spotify-results"></div></section><section class="card"><div class="card-head"><h2>Gespeicherte Auswahl</h2></div><p class="muted tiny">${target?`${esc(target.type)} · ${esc(target.id)}`:'Wähle einen Titel oder eine Playlist in der Suche.'}</p><form id="spotifyForm"><div class="field"><label for="spotifyUrl">Spotify-Link</label><input id="spotifyUrl" name="url" type="url" value="${esc(data.musicUrl||'')}" placeholder="https://open.spotify.com/playlist/…"></div><div class="split"><button class="button secondary" type="submit">Spotify-Link speichern</button>${target?`<a class="button ghost" href="${esc(target.link)}" target="_blank" rel="noopener">In Spotify öffnen ↗</a>`:''}<button class="button" type="button" data-spotify-play>▶ Abspielen</button></div></form></section><p class="tiny muted">Spotify liefert Suche, Metadaten und Cover. Die Wiedergabe läuft über den offiziellen Web Playback SDK; Spotify-Inhalte sind mit Spotify verlinkt. <a href="https://open.spotify.com" target="_blank" rel="noopener">Spotify öffnen ↗</a></p>`}
function renderHistory(){let items=workouts();if(historyFilter!=='Alle')items=items.filter(s=>s.name===historyFilter);return `<div class="eyebrow">DEIN WEG</div><div class="heading-row"><div><h1>Trainingsverlauf</h1><p class="subtitle">Jede Wiederholung bringt dich weiter.</p></div><button class="button secondary" data-action="log-manual">＋ Einheit eintragen</button></div><div class="filter-row"><button class="filter-chip ${historyFilter==='Alle'?'active':''}" data-filter="Alle">Alle</button>${[...new Set(data.history.map(h=>h.name))].map(n=>`<button class="filter-chip ${historyFilter===n?'active':''}" data-filter="${esc(n)}">${esc(n)}</button>`).join('')}</div><section class="card">${items.length?items.map(historyDetailRow).join(''):`<div class="empty"><div class="empty-icon">◷</div><strong>Noch kein Verlauf</strong><p>Starte ein Training und speichere deine Sätze. Hier entsteht deine Trainingshistorie.</p><a class="button" href="#home">Zum Training</a></div>`}</section>`}
function historyRow(s){let count=(s.exercises||[]).reduce((n,e)=>n+(e.sets||[]).length,0);return `<div class="history-item"><div class="history-date"><b>${new Date(s.date+'T12:00:00').getDate()}</b>${new Date(s.date+'T12:00:00').toLocaleDateString('de-DE',{month:'short'})}</div><div class="history-desc"><strong>${esc(s.name)}</strong><span>${exerciseSummary(s)}${volume(s)?` · ${Math.round(volume(s)).toLocaleString('de-DE')} kg Volumen`:''}</span></div><span class="pill">${formatDate(s.date,{weekday:'short'})}</span><button class="icon-action" title="Einheit löschen" data-delete-session="${s.id}">×</button></div>`}
function historyTemplateTarget(session){const exercises=performedExercises(session).map(ex=>{const reps=(ex.sets||[]).map(set=>set.reps).filter(value=>value!==''&&value!=null).map(Number).filter(Number.isFinite),seconds=(ex.sets||[]).map(set=>set.seconds).filter(value=>value!==''&&value!=null).map(Number).filter(Number.isFinite),range=values=>{if(!values.length)return '';const low=Math.min(...values),high=Math.max(...values);return low===high?String(low):`${low}–${high}`};return {name:ex.name,sets:Math.max(1,ex.sets?.length||3),reps:reps.length?range(reps):seconds.length?`${range(seconds)} Sek.`:'8–12'}});return exercises}
function createTemplateFromHistory(id){const session=data.history.find(item=>String(item.id)===String(id));if(!session)return;const suggested=`${session.name} – Vorlage`,name=(prompt('Name der neuen Vorlage:',suggested)||'').trim();if(!name)return;data.plan.push({id:crypto.randomUUID(),name,exercises:historyTemplateTarget(session)});save();render();toast('Vorlage aus dem Training erstellt')}
function historyDetailRow(s){const exercises=s.exercises||[],count=exercises.reduce((n,e)=>n+(e.sets||[]).length,0),date=new Date(s.date+'T12:00:00');return `<details class="history-detail"><summary><div class="history-item"><div class="history-date"><b>${date.getDate()}</b>${date.toLocaleDateString('de-DE',{month:'short'})}</div><div class="history-desc"><strong>${esc(s.name)}</strong><span>${exerciseSummary(s)}${volume(s)?` · ${Math.round(volume(s)).toLocaleString('de-DE')} kg Volumen`:''}</span></div><span class="pill">${formatDate(s.date,{weekday:'short'})}</span><span class="history-chevron" aria-hidden="true">⌄</span></div></summary><div class="history-detail-body">${exercises.length?exercises.map((exercise,index)=>`<section class="history-exercise"><h3>${index+1}. ${esc(exercise.name)}</h3>${exercise.status?`<span class="exercise-status-label">${exercise.status==='skipped'?'Heute ausgelassen':'✓ Fertig'}</span>`:''}${exercise.status==='skipped'?`<p class="tiny muted">Nicht durchgeführt · zählt nicht zur Trainingsleistung.</p>`:(exercise.sets||[]).length?`<div class="history-set-head"><span>Satz</span><span>Gewicht</span><span>Wdh. / Sek.</span></div>${exercise.sets.map((set,i)=>`<div class="history-set"><span>${set.setNo||i+1}</span><span>${set.weight!==''&&set.weight!=null?`${esc(formatWeight(set.weight))} kg`:'–'}</span><span>${set.seconds?`${esc(set.seconds)} Sek.`:set.reps!==''&&set.reps!=null?`${esc(set.reps)} Wdh.`:'–'}</span></div>`).join('')}`:`<p class="tiny muted">Keine Satzwerte gespeichert.</p>`}${exercise.note?`<p class="history-note">${esc(exercise.note)}</p>`:''}</section>`).join(''):`<p class="tiny muted">Für diese Einheit sind keine Übungsdetails gespeichert.</p>`}${s.note?`<p class="history-note session-note"><strong>Einheitsnotiz:</strong> ${esc(s.note)}</p>`:''}<div class="split history-actions">${performedExercises(s).length?`<button class="button secondary small" type="button" data-create-template="${esc(s.id)}">Als Vorlage speichern</button>`:``}<button class="button danger small" type="button" data-delete-session="${esc(s.id)}">Einheit löschen</button></div></div></details>`}
function statsNumber(value){const number=Number(String(value??'').replace(',','.'));return Number.isFinite(number)?number:0}
function statsWeekStart(date){const start=new Date(date);start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7));return start}
function localDateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function statsWeekKey(date){return localDateKey(statsWeekStart(new Date(`${date}T12:00:00`)))}
function statsValueLabel(value,unit){return `${Number(value).toLocaleString('de-DE',{maximumFractionDigits:1})} ${unit}`}
function hasSetMeasurement(set){return ['weight','reps','seconds'].some(key=>set[key]!==''&&set[key]!=null&&String(set[key]).trim()!=='')}
function exerciseProgress(sessions,name){const matching=sessions.flatMap(session=>performedExercises(session).filter(exercise=>exercise.name===name).map(exercise=>({session,exercise}))),allSets=matching.flatMap(item=>item.exercise.sets||[]),mode=allSets.some(set=>statsNumber(set.weight)>0)?'Gewicht':allSets.some(set=>statsNumber(set.seconds)>0)?'Haltezeit':'Wiederholungen',field=mode==='Gewicht'?'weight':mode==='Haltezeit'?'seconds':'reps',points=[];matching.sort((a,b)=>a.session.date.localeCompare(b.session.date)).forEach(({session,exercise})=>{const sets=exercise.sets||[],values=sets.map(set=>statsNumber(set[field])).filter(value=>value>0);if(!values.length)return;const value=Math.max(...values),top=sets.filter(set=>statsNumber(set[field])===value),repsAtTop=Math.max(0,...top.map(set=>statsNumber(set.reps)));points.push({name,date:session.date,value,mode,reps:repsAtTop,sets:sets.length})});return points}
function progressChartSvg(points,unit){if(!points.length)return `<div class="empty"><strong>Noch keine messbaren Satzwerte</strong><p>Gewicht, Wiederholungen oder Sekunden werden hier im Verlauf angezeigt.</p></div>`;let values=points.map(point=>point.value),min=Math.min(...values),max=Math.max(...values);if(min===max){const pad=Math.max(1,max*.08);min=Math.max(0,min-pad);max+=pad}else{const pad=(max-min)*.12;min=Math.max(0,min-pad);max+=pad}const mobile=innerWidth<=650,w=mobile?360:720,h=230,pad={l:mobile?58:70,r:mobile?14:20,t:24,b:42},x=i=>pad.l+(points.length===1?(w-pad.l-pad.r)/2:i*(w-pad.l-pad.r)/(points.length-1)),y=value=>pad.t+(max-value)*(h-pad.t-pad.b)/(max-min),coords=points.map((point,i)=>`${x(i)},${y(point.value)}`).join(' '),ticks=[max,(max+min)/2,min];return `<div class="chart-wrap progress-chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(points[0].mode)}-Fortschritt für ${esc(points[0].name||'Übung')}">${ticks.map((tick,index)=>`<line class="chart-grid" x1="${pad.l}" y1="${pad.t+index*(h-pad.t-pad.b)/2}" x2="${w-pad.r}" y2="${pad.t+index*(h-pad.t-pad.b)/2}"/><text class="chart-label" x="0" y="${pad.t+4+index*(h-pad.t-pad.b)/2}">${esc(statsValueLabel(tick,unit))}</text>`).join('')}<polyline class="chart-line" points="${coords}"/>${points.map((point,i)=>`<circle class="chart-dot" cx="${x(i)}" cy="${y(point.value)}" r="5"><title>${formatDate(point.date)} · ${statsValueLabel(point.value,unit)}${point.reps?` · ${point.reps} Wdh.`:''}</title></circle>`).join('')}<text class="chart-label" x="${pad.l}" y="${h-6}">${formatDate(points[0].date,{day:'numeric',month:'short'})}</text><text class="chart-label" text-anchor="end" x="${w-pad.r}" y="${h-6}">${formatDate(points.at(-1).date,{day:'numeric',month:'short'})}</text></svg></div>`}
function weeklyVolumeChart(sessions){const now=new Date(),current=statsWeekStart(now),weeks=Array.from({length:8},(_,index)=>{const start=new Date(current);start.setDate(start.getDate()-(7*(7-index)));const key=localDateKey(start);return {key,start,total:0,count:0}}),byKey=new Map(weeks.map(week=>[week.key,week]));sessions.forEach(session=>{const week=byKey.get(statsWeekKey(session.date));if(week){week.total+=volume(session);week.count++}});const max=Math.max(1,...weeks.map(week=>week.total)),w=innerWidth<=650?360:720,h=220,pad={l:12,r:12,t:28,b:38},bar=(w-pad.l-pad.r)/8;return `<div class="chart-wrap volume-chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Trainingsvolumen pro Woche der letzten acht Wochen">${weeks.map((week,index)=>{const height=week.total?Math.max(5,(h-pad.t-pad.b)*week.total/max):3,x=pad.l+index*bar+bar*.18,y=h-pad.b-height;return `<rect x="${x}" y="${y}" width="${bar*.64}" height="${height}" rx="7" fill="var(--lime)"><title>${formatDate(week.key,{day:'numeric',month:'short'})} · ${Math.round(week.total).toLocaleString('de-DE')} kg · ${week.count} Einheiten</title></rect><text class="chart-label" text-anchor="middle" x="${pad.l+index*bar+bar/2}" y="${h-10}">${week.start.toLocaleDateString('de-DE',innerWidth<=650?{day:'2-digit',month:'2-digit'}:{day:'numeric',month:'short'})}</text>${week.total?`<text class="chart-label" text-anchor="middle" x="${pad.l+index*bar+bar/2}" y="${Math.max(12,y-7)}">${week.total>=1000?`${(Math.round(week.total/100)/10).toLocaleString('de-DE')}k`:Math.round(week.total).toLocaleString('de-DE')}</text>`:''}`}).join('')}</svg></div>`}
function muscleGroupStats(sessions){const groups=new Map(),catalog=new Map((data.catalog||[]).map(item=>[item.name,item.group||'Sonstige']));sessions.forEach(session=>performedExercises(session).forEach(exercise=>{const sets=(exercise.sets||[]).filter(hasSetMeasurement).length;if(!sets)return;const group=catalog.get(exercise.name)||'Sonstige';groups.set(group,(groups.get(group)||0)+sets)}));return [...groups].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'de'))}
function renderStats(){const sessions=workouts(),names=[...new Set(sessions.flatMap(session=>performedExercises(session).map(exercise=>exercise.name)))].sort((a,b)=>a.localeCompare(b,'de',{sensitivity:'base'})),params=new URLSearchParams(location.hash.split('?')[1]||''),selected=params.get('exercise')||names[0]||'',now=new Date(),thirtyDays=new Date(now);thirtyDays.setDate(thirtyDays.getDate()-29);thirtyDays.setHours(0,0,0,0);const recent=sessions.filter(session=>new Date(`${session.date}T12:00:00`)>=thirtyDays&&session.date<=localDateKey(now)),recentVolume=recent.reduce((sum,session)=>sum+volume(session),0),loggedSets=sessions.reduce((sum,session)=>sum+performedExercises(session).reduce((n,exercise)=>n+(exercise.sets||[]).filter(hasSetMeasurement).length,0),0),weekKeys=new Set(sessions.map(session=>statsWeekKey(session.date))),thisWeekKey=localDateKey(statsWeekStart(now));let streak=0,weekCursor=new Date(statsWeekStart(now));if(!weekKeys.has(thisWeekKey))weekCursor.setDate(weekCursor.getDate()-7);while(weekKeys.has(localDateKey(weekCursor))){streak++;weekCursor.setDate(weekCursor.getDate()-7)}const points=selected?exerciseProgress(sessions,selected):[],mode=points[0]?.mode||'Gewicht',unit=mode==='Gewicht'?'kg':mode==='Haltezeit'?'Sek.':'Wdh.',best=points.length?Math.max(...points.map(point=>point.value)):0,first=points[0]?.value||0,last=points.at(-1)?.value||0,delta=first&&points.length>1?((last-first)/first)*100:null,groups=muscleGroupStats(sessions),maxGroup=Math.max(1,...groups.map(([,count])=>count));let summaryLabel=mode==='Gewicht'?'Schwerster Satz':mode==='Haltezeit'?'Längste Haltezeit':'Meiste Wiederholungen';return `<div class="eyebrow">DEIN FORTSCHRITT</div><div class="heading-row"><div><h1>Deine Auswertung</h1></div></div><div class="grid stats-kpis"><div class="metric"><div class="metric-label">Einheiten · 30 Tage</div><div class="metric-value">${recent.length}</div><div class="metric-note">${sessions.length} insgesamt</div></div><div class="metric"><div class="metric-label">Volumen · 30 Tage</div><div class="metric-value">${Math.round(recentVolume).toLocaleString('de-DE')} <small>kg</small></div><div class="metric-note">Gewicht × Wiederholungen</div></div><div class="metric"><div class="metric-label">Trainingsserie</div><div class="metric-value">${streak} <small>${streak===1?'Woche':'Wochen'}</small></div><div class="metric-note">aufeinanderfolgend</div></div><div class="metric"><div class="metric-label">Arbeitssätze</div><div class="metric-value">${loggedSets}</div><div class="metric-note">mit erfassten Werten</div></div></div><section class="card stats-section"><div class="card-head"><div><h2>Trainingsvolumen</h2><p class="tiny muted">Gewichtete Wiederholungen je Woche · letzte 8 Wochen</p></div></div>${recentVolume>0||sessions.some(session=>volume(session)>0)?weeklyVolumeChart(sessions):`<div class="empty">Hier erscheint dein wöchentliches Volumen, sobald du Gewicht und Wiederholungen protokollierst.</div>`}</section><section class="card stats-section"><div class="card-head stats-exercise-head"><div><h2>Übungsfortschritt</h2><p class="tiny muted">Vergleiche deinen stärksten Satz je Training.</p></div>${names.length?`<label class="stats-select-label"><span class="sr-only">Übung auswählen</span><select data-stats-exercise aria-label="Übung für Fortschritt auswählen">${names.map(name=>`<option value="${esc(name)}" ${name===selected?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`:''}</div>${selected?`${progressChartSvg(points,unit)}${points.length?`<div class="stats-records"><div class="stats-record"><span>${summaryLabel}</span><strong>${statsValueLabel(best,unit)}</strong></div><div class="stats-record"><span>Letzter Eintrag</span><strong>${statsValueLabel(last,unit)}</strong></div><div class="stats-record"><span>Veränderung</span><strong class="${delta===null?'':delta>=0?'positive':'negative'}">${delta===null?'Noch keine Vergleichswerte':`${delta>=0?'+':''}${delta.toLocaleString('de-DE',{maximumFractionDigits:1})}% seit Start`}</strong></div></div><p class="tiny muted stats-footnote">${points.length} Einheiten mit Messwert · ${mode==='Gewicht'?'Punkte zeigen das höchste Gewicht pro Einheit.':'Ohne Gewichtseintrag zeigt das Diagramm Wiederholungen oder Haltezeit.'}</p>`:''}`:`<div class="empty">Füge Übungen zu einem gespeicherten Training hinzu, um Fortschritte zu vergleichen.</div>`}</section><section class="grid stats-lower"><div class="card stats-section"><div class="card-head"><div><h2>Trainierte Muskelgruppen</h2><p class="tiny muted">Arbeitssätze im gesamten Verlauf</p></div></div>${groups.length?`<div class="group-breakdown">${groups.map(([group,count])=>`<div class="group-stat"><div><span>${esc(group)}</span><strong>${count}</strong></div><div class="group-track"><i style="width:${Math.max(5,count/maxGroup*100)}%"></i></div></div>`).join('')}</div>`:`<div class="empty">Noch keine Satzdaten vorhanden.</div>`}</div><div class="card stats-section"><div class="card-head"><div><h2>Zuletzt trainiert</h2><p class="tiny muted">Deine letzten Einheiten</p></div><a href="#history" class="tiny muted">Zum Verlauf →</a></div>${sessions.length?`<div class="stats-recent">${sessions.slice(0,5).map(session=>`<div class="stats-recent-row"><div><strong>${esc(session.name)}</strong><span>${formatDate(session.date,{day:'numeric',month:'short',year:'numeric'})}</span></div><div><b>${performedExercises(session).length}</b><span>Übungen</span></div><div><b>${Math.round(volume(session)).toLocaleString('de-DE')}</b><span>kg Volumen</span></div></div>`).join('')}</div>`:`<div class="empty">Deine gespeicherten Trainingseinheiten erscheinen hier.</div>`}</div></section>`}
function renderSession(){const params=new URLSearchParams(location.hash.split('?')[1]||''),isFree=params.get('free')==='1',id=params.get('id');if(isFree&&!sessionDraft)sessionDraft={id:crypto.randomUUID(),name:'Spontanes Training',exercises:[],values:{}};if(!isFree&&sessionDraft?.sourceWorkoutId!==id){const workout=data.plan.find(item=>item.id===id);if(!workout){location.hash='#plan';return ''}sessionDraft={...structuredClone(workout),exercises:workout.exercises.map(ex=>({...ex,status:"pending"})),sourceWorkoutId:id,values:{}};persistSessionDraft()}const w=sessionDraft;if(!w){location.hash='#plan';return ''}return `<div class="eyebrow">${isFree?'FREIES TRAINING':'VORLAGEN-TRAINING'} · ${new Date().toLocaleDateString('de-DE',{day:'numeric',month:'long'})}</div><div class="heading-row"><div><h1>${esc(w.name)}</h1><p class="subtitle">Die Einheit wird beim Speichern mit dem heutigen Datum protokolliert.</p></div>${isFree?'<button class="button secondary small" type="button" data-action="free-add-exercise">＋ Übung</button>':''}</div><form id="sessionForm" data-workout="${esc(w.id)}" data-free="${isFree}">${w.exercises.length?w.exercises.map((e,i)=>{const previous=lastExerciseUse(e.name)?.exercise.sets||[],draftKey=e.draftKey||(e.draftKey=crypto.randomUUID()),status=isFree?'pending':e.status||'pending';return `<section class="card session-exercise" data-status="${status}"><div class="session-exercise-head"><h3><span class="exercise-number">${i+1}</span><span class="session-exercise-title">${esc(e.name)}<small class="muted">Ziel ${esc(e.reps)}</small></span></h3>${isFree?`<div class="free-exercise-tools"><span class="tiny muted">${e.sets} Sätze</span><button class="icon-action" type="button" aria-label="Satzanzahl verringern" title="Satzanzahl verringern" data-free-set-change="${i}:-1">−</button><button class="icon-action" type="button" aria-label="Satzanzahl erhöhen" title="Satzanzahl erhöhen" data-free-set-change="${i}:1">＋</button><button class="icon-action free-exercise-remove" type="button" aria-label="Übung entfernen" title="Übung entfernen" data-free-exercise-delete="${i}">×</button></div>`:''}</div>${!isFree?`<div class="exercise-status-actions" role="group" aria-label="Status für ${esc(e.name)}"><button type="button" class="button small" data-exercise-index="${i}" data-exercise-status="${status==='completed'?'pending':'completed'}" aria-pressed="${status==='completed'}">${status==='completed'?'✓ Fertig · bearbeiten':'Fertig'}</button><button type="button" class="button secondary small" data-exercise-index="${i}" data-exercise-status="${status==='skipped'?'pending':'skipped'}" aria-pressed="${status==='skipped'}">${status==='skipped'?'Heute ausgelassen · zurücknehmen':'Heute auslassen'}</button></div>${status==='skipped'?'<p class="tiny muted">Heute ausgelassen. Deine Eingaben bleiben zum Wiederaufnehmen erhalten.</p>':status==='completed'?'<p class="tiny muted">Übung abgeschlossen. Zum Ändern auf „Fertig · bearbeiten“ tippen.</p>':''}`:''}<fieldset class="session-set-fields" ${status==='skipped'?'disabled hidden':''}><legend class="sr-only">Satzwerte für ${esc(e.name)}</legend><div class="set-row set-row-head" aria-hidden="true"><span>Satz</span><span>kg</span><span>Wdh.</span><span>Sek.</span></div>${Array.from({length:+e.sets||1},(_,j)=>{const prior=previous.find(set=>set.setNo===j+1)||previous[j];const weight=sessionDraft.values?.[`${draftKey}:${j}:weight`]??formatWeight(prior?.weight??'');return `<div class="set-row"><span>S${j+1}</span><input name="weight-${i}-${j}" ${status==='completed'?'readonly':''} type="text" inputmode="decimal" pattern="[0-9]+(,[0-9]{1,2})?" value="${esc(weight)}" placeholder="kg" aria-label="${esc(e.name)} Satz ${j+1} Gewicht"><input name="reps-${i}-${j}" ${status==='completed'?'readonly':''} type="number" inputmode="numeric" step="1" min="0" value="${esc(sessionDraft.values?.[`${draftKey}:${j}:reps`]??prior?.reps??'')}" placeholder="Wdh" aria-label="${esc(e.name)} Satz ${j+1} Wiederholungen"><input name="seconds-${i}-${j}" ${status==='completed'?'readonly':''} type="number" inputmode="numeric" step="1" min="0" value="${esc(sessionDraft.values?.[`${draftKey}:${j}:seconds`]??prior?.seconds??'')}" placeholder="Sek." aria-label="${esc(e.name)} Satz ${j+1} Dauer in Sekunden"></div>`}).join('')}</fieldset><div class="field" style="margin:12px 0 0"><input name="note-${i}" value="${esc(sessionDraft.values?.[`${draftKey}:note`]||'')}" placeholder="Notiz (optional)" aria-label="Notiz für ${esc(e.name)}"></div></section>`}).join(''):`<section class="card empty"><strong>Noch keine Übungen</strong><p>Füge eine Übung aus dem Katalog hinzu.</p><button class="button secondary" type="button" data-action="free-add-exercise">＋ Übung hinzufügen</button></section>`}<div class="field"><label for="sessionNote">Notiz zur Einheit</label><textarea name="note" id="sessionNote" rows="2" placeholder="Wie lief's heute?">${esc(sessionDraft.values?.sessionNote||'')}</textarea></div>${isFree?`<label class="save-template-option"><input type="checkbox" name="saveTemplate" ${sessionDraft.values?.saveTemplate?'checked':''}> Als Vorlage für später speichern</label><div class="field template-name-field" ${sessionDraft.values?.saveTemplate?'':'hidden'}><label for="templateName">Name der Vorlage</label><input id="templateName" name="templateName" value="${esc(sessionDraft.values?.templateName??w.name)}"></div>`:''}<div class="split session-submit"><button class="button secondary" type="button" data-action="cancel-session">Abbrechen</button><button class="button secondary" type="button" data-action="save-session-draft">Zwischenspeichern</button><button class="button" type="submit">Training speichern ✓</button></div></form>`}
function setSessionExerciseStatus(index,status){const form=$('#sessionForm'),exercise=sessionDraft?.exercises[index];if(!form||!exercise||!sessionDraft.sourceWorkoutId)return;const card=$$('.session-exercise',form)[index];if(status==='completed'){for(const input of $$('input',card)){if(!input.checkValidity()){input.reportValidity();return}}}const values=sessionDraft.values||(sessionDraft.values={});sessionDraft.exercises.forEach((ex,i)=>{ex.draftKey||(ex.draftKey=crypto.randomUUID());for(let j=0;j<(+ex.sets||1);j++)for(const kind of ['weight','reps','seconds']){const input=form.elements[`${kind}-${i}-${j}`];if(input)values[`${ex.draftKey}:${j}:${kind}`]=input.value}values[`${ex.draftKey}:note`]=form.elements[`note-${i}`]?.value||''});values.sessionNote=form.elements.note.value;exercise.status=status;persistSessionDraft();const top=window.scrollY;render();window.scrollTo(0,top);const button=$(`[data-exercise-index="${index}"][data-exercise-status="${status==='pending'?'completed':'pending'}"]`);button?.focus({preventScroll:true})}
