function manualDialog(){const choices=data.plan.map(w=>`<option value="${esc(w.name)}">${esc(w.name)}</option>`).join('');const d=modal(`<h2>Einheit eintragen</h2><p>Ergänze auch vergangene Trainings.</p><form id="manualForm"><div class="field"><label>Einheit</label><select name="name">${choices}<option value="Andere">Andere</option></select></div><div class="field"><label>Datum</label><input name="date" type="date" value="${localDateKey(new Date())}" required></div><div class="field"><label>Notiz</label><input name="note" placeholder="Optional"></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">Eintragen</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();$('#manualForm',d).onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.history.push({id:crypto.randomUUID(),date:f.get('date'),name:f.get('name'),exercises:[],note:f.get('note')});save();d.close();render();toast('Einheit eingetragen')};}
function exportData(){const backup={app:'GrevingFit',formatVersion:1,exportedAt:new Date().toISOString(),data};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`grevingfit-backup-${localDateKey(new Date())}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sicherungsdatei heruntergeladen')}
function isValidFitnessData(state){
 if(!state||!Array.isArray(state.plan)||!Array.isArray(state.history)||('catalog'in state&&!Array.isArray(state.catalog)))return false;
 const text=value=>typeof value==='string'&&value.trim().length>0;
 const target=exercise=>exercise&&text(exercise.name)&&Number.isInteger(Number(exercise.sets))&&Number(exercise.sets)>=1&&Number(exercise.sets)<=20&&(typeof exercise.reps==='string'||typeof exercise.reps==='number');
 const measure=value=>value==null||value===''||(typeof value==='string'||typeof value==='number')&&Number.isFinite(Number(String(value).replace(',','.')))&&Number(String(value).replace(',','.'))>=0;
 const recorded=exercise=>exercise&&text(exercise.name)&&(exercise.status===undefined||['completed','skipped'].includes(exercise.status))&&Array.isArray(exercise.sets)&&exercise.sets.every(set=>set&&typeof set==='object'&&['weight','reps','seconds'].every(key=>measure(set[key])));
 if(state.catalog&&!state.catalog.every(target))return false;
 if(!state.plan.every(workout=>workout&&text(workout.id)&&text(workout.name)&&Array.isArray(workout.exercises)&&workout.exercises.every(target)))return false;
 return state.history.every(workout=>workout&&text(workout.id)&&text(workout.name)&&typeof workout.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(workout.date)&&Number.isFinite(new Date(workout.date+'T12:00:00').getTime())&&localDateKey(new Date(workout.date+'T12:00:00'))===workout.date&&Array.isArray(workout.exercises)&&workout.exercises.every(recorded));
}
function importData(e){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),incoming=['GrevingFit','CarstenFit'].includes(parsed?.app)&&parsed?.data?parsed.data:parsed;if(!isValidFitnessData(incoming))throw Error();if(!confirm('Der Import ersetzt alle aktuell gespeicherten GrevingFit-Daten auf diesem Gerät. Fortfahren?'))return;data=normalizeData(incoming);save();render();toast('Sicherung auf diesem Gerät wiederhergestellt')}catch{alert('Die Datei ist kein gültiges GrevingFit-Backup. Deine vorhandenen Daten bleiben erhalten.')}finally{e.target.value=''}};reader.readAsText(file)}
